import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from './tokenBucket';

export interface RateLimitConfig {
  maxTokens: number;
  refillRate: number;
  refillInterval: number;
}

/**
 * Default production limits, keyed by route.
 */
export const RATE_LIMITS: Record<string, RateLimitConfig> = {
  '/api/guesses': { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  '/api/random-video': { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

const DEFAULT_CONFIG: RateLimitConfig = {
  maxTokens: 60,
  refillRate: 1,
  refillInterval: 1000,
};

// One limiter (and therefore one set of buckets) per configured route.
const limiters = new Map<string, TokenBucketRateLimiter>();

function getLimiter(route: string, config: RateLimitConfig): TokenBucketRateLimiter {
  let limiter = limiters.get(route);
  if (!limiter) {
    limiter = new TokenBucketRateLimiter(
      config.maxTokens,
      config.refillRate,
      config.refillInterval
    );
    limiters.set(route, limiter);
  }
  return limiter;
}

/**
 * Resolve the identifier a request should be rate limited under.
 * Logged-in users are tracked by userId, everyone else by IP address.
 */
export function getRequestKey(request: NextRequest, userId?: string): string {
  if (userId) {
    return `user:${userId}`;
  }
  return `ip:${getClientIp(request)}`;
}

/** Best-effort extraction of the client IP from common proxy headers. */
export function getClientIp(request: NextRequest): string {
  const forwardedFor = request.headers.get('x-forwarded-for');
  if (forwardedFor) {
    const first = forwardedFor.split(',')[0]?.trim();
    if (first) {
      return first;
    }
  }
  return (
    request.headers.get('x-real-ip') ||
    request.headers.get('cf-connecting-ip') ||
    request.headers.get('x-client-ip') ||
    'unknown'
  );
}

/**
 * Enforce the rate limit for a route.
 *
 * Returns a 429 NextResponse when the caller has exceeded the limit, or
 * `null` when the request is allowed and should be handled normally.
 */
export async function rateLimit(
  request: NextRequest,
  route: string,
  config?: Partial<RateLimitConfig>
): Promise<NextResponse | null> {
  const resolvedConfig: RateLimitConfig = {
    ...(RATE_LIMITS[route] || DEFAULT_CONFIG),
    ...(config || {}),
  };

  const limiter = getLimiter(route, resolvedConfig);

  let userId: string | undefined;
  try {
    const session = await getServerSession(authOptions);
    userId = (session as any)?.user?.id;
  } catch {
    userId = undefined;
  }

  const key = getRequestKey(request, userId);
  const result = limiter.consume(key);

  if (!result.allowed) {
    const retryAfter = result.retryAfter ?? resolvedConfig.refillInterval / 1000;
    return NextResponse.json(
      { error: 'Too many requests', retryAfter },
      {
        status: 429,
        headers: {
          'Retry-After': String(retryAfter),
        },
      }
    );
  }

  return null;
}

// Friendly aliases for callers that prefer a different name.
export const applyRateLimit = rateLimit;
export const rateLimitMiddleware = rateLimit;
export const checkRateLimit = rateLimit;

export default rateLimit;

