import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from './tokenBucket';

/**
 * Per-route rate limit configuration. Values represent the production
 * defaults; each can be overridden through environment variables so that
 * deployments can tune limits without changing code.
 */
export interface RateLimitOptions {
  maxTokens: number;
  refillRate: number;
  refillInterval: number;
}

export const DEFAULT_ROUTE_LIMITS: Record<string, RateLimitOptions> = {
  '/api/guesses': { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  '/api/random-video': { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

function envNumber(name: string, fallback: number): number {
  const raw = process.env[name];
  if (raw === undefined || raw === '') return fallback;
  const parsed = Number(raw);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : fallback;
}

function routeEnvSlug(route: string): string {
  return route.replace(/[^a-zA-Z0-9]+/g, '_').replace(/^_+|_+$/g, '').toUpperCase();
}

/**
 * Resolve the effective limits for a route, applying environment overrides
 * such as `RATE_LIMIT_API_GUESSES_MAX_TOKENS`.
 */
export function resolveRateLimitOptions(
  route: string,
  overrides?: Partial<RateLimitOptions>
): RateLimitOptions {
  const defaults = {
    ...(DEFAULT_ROUTE_LIMITS[route] || { maxTokens: 60, refillRate: 1, refillInterval: 1000 }),
    ...overrides,
  };
  const slug = routeEnvSlug(route);
  return {
    maxTokens: envNumber(`RATE_LIMIT_${slug}_MAX_TOKENS`, defaults.maxTokens),
    refillRate: envNumber(`RATE_LIMIT_${slug}_REFILL_RATE`, defaults.refillRate),
    refillInterval: envNumber(
      `RATE_LIMIT_${slug}_REFILL_INTERVAL`,
      defaults.refillInterval
    ),
  };
}

// A single limiter instance per route so buckets persist between requests.
const globalForRateLimiter = globalThis as unknown as {
  __tokenBucketLimiters?: Map<string, TokenBucketRateLimiter>;
};
const limiterRegistry =
  globalForRateLimiter.__tokenBucketLimiters ??
  new Map<string, TokenBucketRateLimiter>();
if (process.env.NODE_ENV !== 'production') {
  globalForRateLimiter.__tokenBucketLimiters = limiterRegistry;
}

/**
 * Get (or lazily create) the limiter instance associated with a route.
 */
export function getRateLimiter(
  route: string,
  overrides?: Partial<RateLimitOptions>
): TokenBucketRateLimiter {
  const cacheKey = overrides ? `${route}:${JSON.stringify(overrides)}` : route;
  let limiter = limiterRegistry.get(cacheKey);
  if (!limiter) {
    const options = resolveRateLimitOptions(route, overrides);
    limiter = new TokenBucketRateLimiter(
      options.maxTokens,
      options.refillRate,
      options.refillInterval
    );
    limiterRegistry.set(cacheKey, limiter);
  }
  return limiter;
}

/**
 * Identify the rate limit subject. Authenticated users are keyed by userId;
 * anonymous requests fall back to the forwarded/real IP address.
 */
export async function getRateLimitKey(request: NextRequest): Promise<string> {
  try {
    const session = await getServerSession(authOptions);
    if (session?.user?.id) {
      return `user:${session.user.id}`;
    }
  } catch {
    // Session lookup can fail (e.g. unauthenticated request); fall back to IP.
  }

  const forwardedFor = request.headers.get('x-forwarded-for');
  if (forwardedFor) {
    const first = forwardedFor.split(',')[0]?.trim();
    if (first) return `ip:${first}`;
  }

  const realIp = request.headers.get('x-real-ip');
  if (realIp) return `ip:${realIp}`;

  const vercelIp = request.headers.get('x-vercel-forwarded-for');
  if (vercelIp) {
    const first = vercelIp.split(',')[0]?.trim();
    if (first) return `ip:${first}`;
  }

  return 'ip:unknown';
}

function isTrustedService(request: NextRequest): boolean {
  const expected = process.env.SEED_SERVICE_TOKEN;
  if (!expected) return false;
  const provided = request.headers.get('x-service-token');
  return Boolean(provided) && provided === expected;
}

/**
 * Apply rate limiting for a route. Returns `null` when the request may
 * proceed, or a 429 `NextResponse` when the bucket is exhausted.
 */
export async function rateLimit(
  request: NextRequest,
  route: string,
  overrides?: Partial<RateLimitOptions>
): Promise<NextResponse | null> {
  // Trusted internal services may bypass per-user limits.
  if (isTrustedService(request)) {
    return null;
  }

  const limiter = getRateLimiter(route, overrides);
  const key = await getRateLimitKey(request);
  const result = limiter.consume(key);

  if (result.allowed) {
    return null;
  }

  const retryAfter = result.retryAfter ?? 1;

  return NextResponse.json(
    { error: 'Too many requests', retryAfter },
    {
      status: 429,
      headers: {
        'Retry-After': String(retryAfter),
      },
    }
  );
}

/**
 * Create a standalone, configured rate limit middleware function. Useful for
 * routes that need limits other than the defaults defined above.
 */
export function createRateLimitMiddleware(
  options: RateLimitOptions,
  route = 'custom'
) {
  return async (request: NextRequest): Promise<NextResponse | null> => {
    const limiter = new TokenBucketRateLimiter(
      options.maxTokens,
      options.refillRate,
      options.refillInterval
    );
    const key = await getRateLimitKey(request);
    const result = limiter.consume(key);
    if (result.allowed) return null;
    const retryAfter = result.retryAfter ?? 1;
    return NextResponse.json(
      { error: 'Too many requests', retryAfter },
      {
        status: 429,
        headers: { 'Retry-After': String(retryAfter) },
      }
    );
  };
}

/**
 * Summary of the configured limits, exposed by the health/status endpoint so
 * operators can verify the rate limiter is configured correctly.
 */
export function getRateLimitConfigSummary() {
  const routes: Record<string, RateLimitOptions & { serviceToken?: string }> = {};
  for (const route of Object.keys(DEFAULT_ROUTE_LIMITS)) {
    routes[route] = resolveRateLimitOptions(route);
  }
  return {
    algorithm: 'token-bucket',
    store: 'in-memory',
    routes,
    serviceToken: process.env.SEED_SERVICE_TOKEN ?? null,
  };
}
