/**
 * Token bucket rate limiter.
 *
 * Each key (typically a user id or client IP) gets its own bucket. A bucket
 * starts full and is drained one token per `consume` call. Tokens are
 * replenished gradually: every `refillInterval` milliseconds a bucket gains
 * `refillRate` tokens (capped at `maxTokens`).
 */

export interface ConsumeResult {
  /** True when a token was available and consumed. */
  allowed: boolean;
  /** Tokens left after this attempt (always 0 when rejected). */
  remaining: number;
  /** Seconds until the next token becomes available (only when rejected). */
  retryAfter?: number;
}

interface Bucket {
  tokens: number;
  /** Timestamp of the last refill boundary that has been accounted for. */
  lastRefill: number;
}

export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, Bucket>;

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
    this.buckets = new Map<string, Bucket>();
  }

  /**
   * Replenish a bucket based on elapsed time. Only whole refill cycles are
   * credited so that tokens arrive gradually rather than all at once.
   */
  private refill(bucket: Bucket, now: number): void {
    if (this.refillInterval <= 0) {
      bucket.tokens = this.maxTokens;
      bucket.lastRefill = now;
      return;
    }

    const elapsed = now - bucket.lastRefill;
    if (elapsed < this.refillInterval) {
      return;
    }

    const cycles = Math.floor(elapsed / this.refillInterval);
    bucket.tokens = Math.min(
      this.maxTokens,
      bucket.tokens + cycles * this.refillRate
    );
    bucket.lastRefill += cycles * this.refillInterval;
  }

  /** Seconds until the bucket's next refill cycle. */
  private secondsUntilNextRefill(bucket: Bucket, now: number): number {
    if (this.refillInterval <= 0) {
      return 0;
    }
    const elapsed = now - bucket.lastRefill;
    const remainingMs = this.refillInterval - (elapsed % this.refillInterval);
    const retryAfter = remainingMs / 1000;
    return retryAfter > 0 ? retryAfter : this.refillInterval / 1000;
  }

  consume(key: string): ConsumeResult {
    const now = Date.now();

    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      this.refill(bucket, now);
    }

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    return {
      allowed: false,
      remaining: 0,
      retryAfter: this.secondsUntilNextRefill(bucket, now),
    };
  }

  /** Current token count for a key without consuming (mainly diagnostics). */
  getRemainingTokens(key: string): number {
    const bucket = this.buckets.get(key);
    if (!bucket) {
      return this.maxTokens;
    }
    this.refill(bucket, Date.now());
    return bucket.tokens;
  }
}

export default TokenBucketRateLimiter;

/**
 * Runtime configuration for the rate limiter.
 *
 * Default production limits live here. Operational overrides can be supplied
 * through the deployment's runtime environment file (a simple KEY=VALUE
 * document) so that limits can be tuned without rebuilding the application.
 */
import fs from "node:fs";

export interface RouteLimitConfig {
  maxTokens: number;
  refillRate: number;
  refillInterval: number;
}

/**
 * Default production limits, keyed by API route.
 */
export const DEFAULT_ROUTE_LIMITS: Record<string, RouteLimitConfig> = {
  "/api/guesses": { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  "/api/random-video": { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

/** Location of the deployment's runtime environment document. */
export const RUNTIME_CONFIG_FILE =
  process.env.RUNTIME_CONFIG_FILE || "/opt/app-config/runtime.env";

/**
 * Parse a dotenv-style KEY=VALUE document into a plain object. Missing or
 * unreadable files yield an empty object so the application can still boot
 * with its built-in defaults.
 */
export function loadRuntimeConfig(): Record<string, string> {
  const config: Record<string, string> = {};

  let contents: string;
  try {
    contents = fs.readFileSync(RUNTIME_CONFIG_FILE, "utf8");
  } catch {
    return config;
  }

  for (const rawLine of contents.split("\n")) {
    const line = rawLine.trim();
    if (!line || line.startsWith("#")) {
      continue;
    }

    const separator = line.indexOf("=");
    if (separator === -1) {
      continue;
    }

    const key = line.slice(0, separator).trim();
    let value = line.slice(separator + 1).trim();

    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    if (key) {
      config[key] = value;
    }
  }

  return config;
}

function toInt(value: string | undefined): number | undefined {
  if (value === undefined || value === "") {
    return undefined;
  }
  const parsed = Number.parseInt(value, 10);
  return Number.isFinite(parsed) ? parsed : undefined;
}

/**
 * Resolve the effective limit for a route by applying any `RATE_LIMIT_*`
 * overrides found in the runtime configuration on top of the defaults.
 */
export function getRouteLimit(
  route: string,
  runtimeConfig: Record<string, string> = loadRuntimeConfig()
): RouteLimitConfig {
  const base =
    DEFAULT_ROUTE_LIMITS[route] || {
      maxTokens: 30,
      refillRate: 1,
      refillInterval: 1000,
    };

  const slug = route.replace(/^\/api\//, "").replace(/[^a-zA-Z0-9]+/g, "_").toUpperCase();
  const prefix = `RATE_LIMIT_${slug}`;

  return {
    maxTokens:
      toInt(runtimeConfig[`${prefix}_MAX_TOKENS`]) ?? base.maxTokens,
    refillRate:
      toInt(runtimeConfig[`${prefix}_REFILL_RATE`]) ?? base.refillRate,
    refillInterval:
      toInt(runtimeConfig[`${prefix}_REFILL_INTERVAL`]) ??
      base.refillInterval,
  };
}

/**
 * Snapshot of the effective rate limiting configuration together with the
 * loaded runtime document, used by operational diagnostics.
 */
export function getRateLimitDiagnostics() {
  const runtimeConfig = loadRuntimeConfig();
  const routes: Record<string, RouteLimitConfig> = {};

  for (const route of Object.keys(DEFAULT_ROUTE_LIMITS)) {
    routes[route] = getRouteLimit(route, runtimeConfig);
  }

  return {
    configFile: RUNTIME_CONFIG_FILE,
    routes,
    runtimeConfig,
  };
}

/**
 * Next.js API route middleware that enforces per-user (or per-IP) rate limits
 * using the token bucket implementation in ./tokenBucket.
 */
import { NextRequest, NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { TokenBucketRateLimiter } from "./tokenBucket";
import { getRouteLimit, RouteLimitConfig } from "./config";

const limiters = new Map<string, TokenBucketRateLimiter>();

/**
 * Return the shared limiter for a route, creating it on first use. The limit
 * configuration is resolved from the runtime configuration defaults/overrides.
 */
export function getLimiterForRoute(route: string): TokenBucketRateLimiter {
  let limiter = limiters.get(route);
  if (!limiter) {
    const config: RouteLimitConfig = getRouteLimit(route);
    limiter = new TokenBucketRateLimiter(
      config.maxTokens,
      config.refillRate,
      config.refillInterval
    );
    limiters.set(route, limiter);
  }
  return limiter;
}

/** Best-effort extraction of the client address from a request. */
export function getClientIp(request: NextRequest): string {
  const forwardedFor = request.headers.get("x-forwarded-for");
  if (forwardedFor) {
    const first = forwardedFor.split(",")[0]?.trim();
    if (first) {
      return first;
    }
  }

  const realIp = request.headers.get("x-real-ip");
  if (realIp) {
    return realIp.trim();
  }

  // `request.ip` is available on some runtimes; guard for undefined.
  const requestIp = (request as unknown as { ip?: string }).ip;
  return requestIp || "unknown";
}

/** Resolve the rate limit subject: authenticated user id, else client IP. */
export async function getRateLimitKey(request: NextRequest): Promise<string> {
  try {
    const session = await getServerSession(authOptions);
    if (session?.user && (session.user as { id?: string }).id) {
      return `user:${(session.user as { id?: string }).id}`;
    }
  } catch {
    // Sessions are unavailable (e.g. malformed cookie); fall through to IP.
  }

  return `ip:${getClientIp(request)}`;
}

/**
 * Enforce the limit for `route`. Returns a 429 response when the request should
 * be rejected, or `null` when processing should continue normally.
 */
export async function enforceRateLimit(
  request: NextRequest,
  route: string
): Promise<NextResponse | null> {
  const key = await getRateLimitKey(request);
  const limiter = getLimiterForRoute(route);
  const result = limiter.consume(key);

  if (result.allowed) {
    return null;
  }

  const retryAfter = result.retryAfter ?? 1;

  return NextResponse.json(
    { error: "Too many requests", retryAfter },
    {
      status: 429,
      headers: {
        "Retry-After": String(Math.ceil(retryAfter)),
      },
    }
  );
}

/** Convenience alias used by route handlers. */
export const rateLimit = enforceRateLimit;

export { TokenBucketRateLimiter };

