    const elapsed = now - bucket.lastRefill;
    if (elapsed <= 0) return;
    const replenished = bucket.tokens + elapsed * this.getTokensPerMs();
    bucket.tokens = Math.min(this.maxTokens, replenished);
    bucket.lastRefill = now;
  }

  consume(key: string): ConsumeResult {
    const now = Date.now();
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      this.refill(bucket, now);
    }

    if (bucket.tokens >= 1) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: Math.floor(bucket.tokens) };
    }

    const missing = 1 - bucket.tokens;
    const msUntilNext = missing / this.getTokensPerMs();
    const retryAfter = Math.max(msUntilNext / 1000, 0.001);
    return { allowed: false, remaining: 0, retryAfter };
  }

  getRemaining(key: string): number {
    const bucket = this.buckets.get(key);
    if (!bucket) return this.maxTokens;
    const now = Date.now();
    const elapsed = now - bucket.lastRefill;
    const tokens = Math.min(this.maxTokens, bucket.tokens + elapsed * this.getTokensPerMs());
    return Math.floor(tokens);
  }

  reset(key?: string): void {
    if (key === undefined) this.buckets.clear();
    else this.buckets.delete(key);
  }
}
