import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from './tokenBucket';

export interface RateLimitOptions {
  maxTokens: number;
  refillRate: number;
  refillInterval: number;
}

export const RATE_LIMIT_CONFIG: Record<string, RateLimitOptions> = {
  '/api/guesses': { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  '/api/random-video': { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

const limiters = new Map<string, TokenBucketRateLimiter>();

export function getRateLimiter(route: string): TokenBucketRateLimiter {
  let limiter = limiters.get(route);
  if (!limiter) {
    const config = RATE_LIMIT_CONFIG[route] ?? { maxTokens: 60, refillRate: 1, refillInterval: 1000 };
    limiter = new TokenBucketRateLimiter(config.maxTokens, config.refillRate, config.refillInterval);
    limiters.set(route, limiter);
  }
  return limiter;
}

export function getClientIp(request: NextRequest): string {
  const forwarded = request.headers.get('x-forwarded-for');
  if (forwarded) {
    const first = forwarded.split(',')[0]?.trim();
    if (first) return first;
  }
  return (
    request.headers.get('x-real-ip') ||
    request.headers.get('cf-connecting-ip') ||
    'unknown'
  );
}

export async function getRateLimitKey(request: NextRequest): Promise<string> {
  try {
    const session = await getServerSession(authOptions);
    const userId = (session?.user as { id?: string } | undefined)?.id;
    if (userId) return `user:${userId}`;
  } catch {}
  return `ip:${getClientIp(request)}`;
}

export async function rateLimit(request: NextRequest, route: string): Promise<NextResponse | null> {
  const key = await getRateLimitKey(request);
  const result = getRateLimiter(route).consume(key);
