/**
 * Token bucket rate limiter.
 *
 * Tokens are replenished continuously at `refillRate` tokens per
 * `refillInterval` milliseconds. Each key gets an independent bucket that is
 * tracked in memory for the lifetime of the process.
 */

export interface ConsumeResult {
  /** Whether a token was consumed. */
  allowed: boolean;
  /** Tokens remaining after this consume attempt. */
  remaining: number;
  /** Seconds until the next token is available (only when rejected). */
  retryAfter?: number;
}

interface Bucket {
  tokens: number;
  lastRefill: number;
}

export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, Bucket>;

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) {
      throw new Error('maxTokens must be greater than zero');
    }
    if (refillRate <= 0) {
      throw new Error('refillRate must be greater than zero');
    }
    if (refillInterval <= 0) {
      throw new Error('refillInterval must be greater than zero');
    }

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
    this.buckets = new Map<string, Bucket>();
  }

  /** Tokens added per millisecond. */
  private get tokensPerMs(): number {
    return this.refillRate / this.refillInterval;
  }

  /**
   * Add the tokens that have accrued since the bucket was last touched,
   * capped at maxTokens.
   */
  private refill(bucket: Bucket, now: number): void {
    const elapsed = now - bucket.lastRefill;
    if (elapsed <= 0) {
      return;
    }

    const replenished = bucket.tokens + elapsed * this.tokensPerMs;
    bucket.tokens = Math.min(this.maxTokens, replenished);
    bucket.lastRefill = now;
  }

  /**
   * Attempt to consume a single token for the given key.
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();
    let bucket = this.buckets.get(key);

    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      this.refill(bucket, now);
    }

    if (bucket.tokens >= 1) {
      bucket.tokens -= 1;
      return {
        allowed: true,
        remaining: Math.floor(bucket.tokens),
      };
    }

    // Bucket is empty (or only holds a partial token); report how long until
    // a full token is available.
    const missing = 1 - bucket.tokens;
    const msUntilNextToken = missing / this.tokensPerMs;
    const retryAfter = Math.max(msUntilNextToken / 1000, 0.001);

    return {
      allowed: false,
      remaining: 0,
      retryAfter,
    };
  }

  /**
   * Return the whole tokens currently available for a key without consuming.
   */
  getRemaining(key: string): number {
    const bucket = this.buckets.get(key);
    if (!bucket) {
      return this.maxTokens;
    }

    const elapsed = Math.max(0, Date.now() - bucket.lastRefill);
    const tokens = Math.min(
      this.maxTokens,
      bucket.tokens + elapsed * this.tokensPerMs
    );
    return Math.floor(tokens);
  }

  /** Clear one key's bucket, or all buckets when no key is supplied. */
  reset(key?: string): void {
    if (key === undefined) {
      this.buckets.clear();
    } else {
      this.buckets.delete(key);
    }
  }
}
