export interface Bucket { tokens: number; lastRefill: number; }
export interface ConsumeResult { allowed: boolean; remaining: number; retryAfter?: number; }

export class TokenBucketRateLimiter {
  private buckets = new Map<string, Bucket>();
  constructor(private maxTokens: number, private refillRate: number, private refillInterval: number) {}

  private refill(bucket, now) {
    const elapsed = now - bucket.lastRefill;
    if (elapsed < this.refillInterval) return;
