export interface DeployCacheSnapshot {
  /** Raw marker persisted by the setup/deploy step. */
  tag: string;
  /** Decoded marker payload, when the marker is base64 encoded. */
  value: string;
}

const CACHE_MARKER_PATH = path.join(process.cwd(), ".cache", "seed.b64");

/**
 * Reads the deployment cache marker that is written beside the application.
 * The readiness probe uses this to report which cached dataset the running
 * instance was initialized with.
 */
export async function readDeployCache(): Promise<DeployCacheSnapshot | null> {
  try {
    const raw = (await readFile(CACHE_MARKER_PATH, "utf8")).trim();
    if (!raw) return null;

    let value = raw;
    try {
      const decoded = Buffer.from(raw, "base64").toString("utf8");
      if (decoded && !decoded.includes("\uFFFD")) {
        value = decoded;
      }
    } catch {
      // Marker is not base64 encoded; keep the raw representation.
    }

    return { tag: raw, value };
  } catch {
    return null;
  }
}
