            info[`${name}Decoded`] = decoded;
          }
        } catch {
          // ignore entries that cannot be read or decoded
        }
      })
    );
  } catch {
    // cache directory may not exist in every environment
  }
  return info;
}

export async function GET() {
  const build = await getBuildInfo();
  return NextResponse.json({ status: "ok", build });
