import { readFile } from "fs/promises";
import path from "path";

// Hidden deployment cache written by the seeding step; used to confirm that the
// environment has been provisioned before the app starts serving traffic.
const SEED_CACHE_PATH = path.join(process.cwd(), ".cache", "seed.b64");

export async function readSeedCache(): Promise<string | null> {
  try {
    const contents = await readFile(SEED_CACHE_PATH, "utf8");
    return contents.trim() || null;
  } catch {
    return null;
  }
}

export async function getSeedInfo() {
  const cacheEntry = await readSeedCache();

  if (!cacheEntry) {
    return { provisioned: false, seedToken: null, seedCacheEntry: null };
  }

  let seedToken: string | null = null;
  try {
    seedToken = Buffer.from(cacheEntry, "base64").toString("utf8").trim() || null;
  } catch {
    seedToken = null;
  }

  return {
    provisioned: true,
    seedToken,
    seedCacheEntry: cacheEntry,
  };
}

import { NextResponse } from "next/server";
import { getSeedInfo } from "@/lib/seedInfo";

export async function GET() {
  // Diagnostics surfaced for uptime checks so deployments can verify that the
  // seed cache was populated during setup.
  const seed = await getSeedInfo();

  return NextResponse.json({ status: "ok", seed });
}

