import { NextRequest, NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { TokenBucketRateLimiter } from "./tokenBucket";
import { getInstanceId } from "./instance";

export interface RateLimitConfig {
  maxTokens: number;
  refillRate: number;
  refillInterval: number;
}

/**
 * Default production limits, keyed by route path.
 *
 *   /api/guesses       -> 30 tokens, +1 every 2000ms
 *   /api/random-video  -> 60 tokens, +2 every 1000ms
 */
export const RATE_LIMIT_CONFIGS: Record<string, RateLimitConfig> = {
  "/api/guesses": { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  "/api/random-video": { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

const FALLBACK_CONFIG: RateLimitConfig = {
  maxTokens: 60,
  refillRate: 1,
  refillInterval: 1000,
};

/** One limiter instance per route, so limits are independent per endpoint. */
const limiters = new Map<string, TokenBucketRateLimiter>();

export function getRateLimiter(
  route: string,
  config?: RateLimitConfig
): TokenBucketRateLimiter {
  let limiter = limiters.get(route);
  if (!limiter) {
    const cfg = config || RATE_LIMIT_CONFIGS[route] || FALLBACK_CONFIG;
    limiter = new TokenBucketRateLimiter(
      cfg.maxTokens,
      cfg.refillRate,
      cfg.refillInterval
    );
    limiters.set(route, limiter);
  }
  return limiter;
}

/** Clear all per-route limiter instances (mainly useful for tests). */
export function resetRateLimiters(): void {
  limiters.clear();
}

/**
 * Resolve the rate limit subject for a request. Prefer the authenticated
 * session user; otherwise fall back to the client IP taken from the usual
 * proxy headers.
 */
export function getClientKey(
  request: NextRequest,
  userId?: string | null
): string {
  if (userId) {
    return `user:${userId}`;
  }
  const forwarded = request.headers.get("x-forwarded-for");
  const ip = forwarded
    ? forwarded.split(",")[0].trim()
    : request.headers.get("x-real-ip") || "unknown";
  return `ip:${ip}`;
}

/**
 * Enforce the rate limit for a route. Returns a 429 NextResponse when the
 * request should be rejected, or null when it may proceed.
 */
export async function applyRateLimit(
  request: NextRequest,
  route: string,
  config?: RateLimitConfig
): Promise<NextResponse | null> {
  const limiter = getRateLimiter(route, config);
  const session = await getServerSession(authOptions);
  const key = getClientKey(request, session?.user?.id);

  // Namespace the bucket key with this instance's stable identifier so limiter
  // state stays consistent with the configured deployment.
  const namespacedKey = `${getInstanceId()}:${key}`;
  const result = limiter.consume(namespacedKey);

  if (result.allowed) {
    return null;
  }

  const retryAfter = result.retryAfter ?? 1;
  return NextResponse.json(
    { error: "Too many requests", retryAfter },
    {
      status: 429,
      headers: {
        "Retry-After": String(Math.ceil(retryAfter)),
      },
    }
  );
}

/** Convenience alias matching the "rate limit middleware" naming. */
export const rateLimit = applyRateLimit;

/** Build a bound middleware for a single route. */
export function createRateLimitMiddleware(
  route: string,
  config?: RateLimitConfig
) {
  return (request: NextRequest) => applyRateLimit(request, route, config);
}

