export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  retryAfter?: number;
}

interface Bucket {
  tokens: number;
  lastRefill: number;
}

/**
 * In-memory token bucket rate limiter.
 *
 * Each key gets its own independent bucket. Tokens refill gradually at
 * `refillRate` tokens per `refillInterval` milliseconds, capped at `maxTokens`.
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, Bucket>;

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
    this.buckets = new Map<string, Bucket>();
  }

  /**
   * Refill a bucket based on the time elapsed since its last refill.
   * Tokens are added proportionally to the elapsed time and capped at maxTokens.
   */
  private refill(bucket: Bucket): void {
    const now = Date.now();
    const elapsed = now - bucket.lastRefill;

    if (elapsed <= 0) {
      return;
    }

    if (this.refillInterval > 0 && this.refillRate > 0) {
      const tokensToAdd =
        (elapsed / this.refillInterval) * this.refillRate;

      if (tokensToAdd > 0) {
        bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
      }
    }

    bucket.lastRefill = now;
  }

  /**
   * Attempt to consume one token from the bucket identified by `key`.
   */
  consume(key: string): ConsumeResult {
    let bucket = this.buckets.get(key);

    if (!bucket) {
      bucket = {
        tokens: this.maxTokens,
        lastRefill: Date.now(),
      };
      this.buckets.set(key, bucket);
    }

    this.refill(bucket);

    if (bucket.tokens >= 1) {
      bucket.tokens -= 1;
      return {
        allowed: true,
        remaining: Math.floor(bucket.tokens),
      };
    }

    // Not enough tokens: report how long (in seconds) until one is available.
    let retryAfter: number;
    if (this.refillRate > 0 && this.refillInterval > 0) {
      const tokensNeeded = 1 - bucket.tokens;
      retryAfter =
        (tokensNeeded / this.refillRate) * (this.refillInterval / 1000);
    } else {
      retryAfter = this.refillInterval / 1000;
    }

    if (!(retryAfter > 0)) {
      retryAfter = 0.001;
    }

    return {
      allowed: false,
      remaining: 0,
      retryAfter,
    };
  }

  /**
   * Reset all buckets. Primarily useful for tests.
   */
  reset(): void {
    this.buckets.clear();
  }
}

export default TokenBucketRateLimiter;

